import { useContext, useEffect, useState } from "react";
import { Context } from "./usecontext";
import { useNavigate } from "react-router-dom";
import Swal from "sweetalert2";

// Pagination Component for Admin Users Management
const Pagination = ({ totalItems, itemsPerPage, currentPage, onPageChange, onPerPageChange }) => {
    const totalPages = Math.ceil(totalItems / itemsPerPage) || 1;
    const startItem = totalItems === 0 ? 0 : (currentPage - 1) * itemsPerPage + 1;
    const endItem = Math.min(currentPage * itemsPerPage, totalItems);

    const getPageNumbers = () => {
        const pages = [];
        const maxPagesToShow = 5;
        let startPage = Math.max(1, currentPage - Math.floor(maxPagesToShow / 2));
        let endPage = Math.min(totalPages, startPage + maxPagesToShow - 1);

        if (endPage - startPage + 1 < maxPagesToShow) {
            startPage = Math.max(1, endPage - maxPagesToShow + 1);
        }

        for (let i = startPage; i <= endPage; i++) {
            pages.push(i);
        }
        return pages;
    };

    return (
        <div className="d-flex flex-wrap justify-content-between align-items-center gap-3 mt-4 pt-3 border-top">
            <div className="text-muted small">
                Showing <strong className="text-dark">{startItem}</strong> to <strong className="text-dark">{endItem}</strong> of <strong className="text-dark">{totalItems}</strong> users
            </div>

            <div className="d-flex align-items-center gap-3">
                <div className="d-flex align-items-center gap-2">
                    <span className="small text-muted text-nowrap">Show:</span>
                    <select
                        className="form-select form-select-sm"
                        style={{ width: "75px" }}
                        value={itemsPerPage}
                        onChange={(e) => {
                            onPerPageChange(Number(e.target.value));
                            onPageChange(1);
                        }}
                    >
                        <option value={6}>6</option>
                        <option value={12}>12</option>
                        <option value={24}>24</option>
                        <option value={48}>48</option>
                    </select>
                </div>

                <nav aria-label="User navigation">
                    <ul className="pagination pagination-sm mb-0">
                        <li className={`page-item ${currentPage === 1 ? 'disabled' : ''}`}>
                            <button className="page-link" onClick={() => onPageChange(1)}>
                                &laquo;&laquo;
                            </button>
                        </li>
                        <li className={`page-item ${currentPage === 1 ? 'disabled' : ''}`}>
                            <button className="page-link" onClick={() => onPageChange(currentPage - 1)}>
                                &laquo;
                            </button>
                        </li>

                        {getPageNumbers().map(p => (
                            <li key={p} className={`page-item ${currentPage === p ? 'active' : ''}`}>
                                <button className="page-link" onClick={() => onPageChange(p)}>
                                    {p}
                                </button>
                            </li>
                        ))}

                        <li className={`page-item ${currentPage === totalPages ? 'disabled' : ''}`}>
                            <button className="page-link" onClick={() => onPageChange(currentPage + 1)}>
                                &raquo;
                            </button>
                        </li>
                        <li className={`page-item ${currentPage === totalPages ? 'disabled' : ''}`}>
                            <button className="page-link" onClick={() => onPageChange(totalPages)}>
                                &raquo;&raquo;
                            </button>
                        </li>
                    </ul>
                </nav>
            </div>
        </div>
    );
};

export const Admin = () => {
    const [d, setd] = useState([]);
    const [loading, setLoading] = useState(true);

    // Per-row state management
    const [pendingRoles, setPendingRoles] = useState({});
    const [pendingStatuses, setPendingStatuses] = useState({});

    // Filter & Pagination States
    const [searchTerm, setSearchTerm] = useState("");
    const [roleFilter, setRoleFilter] = useState("all");
    const [statusFilter, setStatusFilter] = useState("all");
    const [viewMode, setViewMode] = useState("grid"); // "grid" or "table"
    const [currentPage, setCurrentPage] = useState(1);
    const [itemsPerPage, setItemsPerPage] = useState(6);

    const navigate = useNavigate();
    const { utype } = useContext(Context);

    useEffect(() => {
        show();
    }, []);

    const show = async () => {
        setLoading(true);
        try {
            const result = await fetch("https://elcto-1.onrender.com/api/users", {
                method: "get"
            });
            if (result.ok) {
                const res = await result.json();
                if (res.statuscode === 1) {
                    setd(res.data);
                } else {
                    Swal.fire("Error", "Failed to fetch user list", "error");
                }
            }
        } catch (err) {
            console.error("Error fetching users:", err);
        } finally {
            setLoading(false);
        }
    };

    const admin = async (id) => {
        const selectedRole = pendingRoles[id];
        if (!selectedRole) {
            Swal.fire("Info", "Please select a user role first.", "info");
            return;
        }

        const confirm = await Swal.fire({
            title: "Change User Role?",
            text: `Set user role to "${selectedRole}"?`,
            icon: "question",
            showCancelButton: true,
            confirmButtonColor: "#0d6efd",
            confirmButtonText: "Yes, Change Role"
        });

        if (!confirm.isConfirmed) return;

        try {
            const data = { ad: selectedRole };
            const result = await fetch(`https://elcto-1.onrender.com/api/makeadmin/${id}`, {
                method: "put",
                body: JSON.stringify(data),
                headers: { "Content-type": "application/json;charset=UTF-8" }
            });
            if (result.ok) {
                const res = await result.json();
                if (res.statuscode === 1) {
                    Swal.fire({
                        title: "Success!",
                        text: "User type changed successfully.",
                        icon: "success",
                        timer: 1500,
                        showConfirmButton: false
                    });
                    show();
                } else {
                    Swal.fire("Error", "Failed to update user role", "error");
                }
            }
        } catch (err) {
            Swal.fire("Error", "Network error updating role", "error");
        }
    };

    const changeStatus = async (id) => {
        const selectedStatus = pendingStatuses[id];
        if (!selectedStatus) {
            Swal.fire("Info", "Please select a status first.", "info");
            return;
        }

        const confirm = await Swal.fire({
            title: "Change User Status?",
            text: `Set user status to "${selectedStatus}"?`,
            icon: "warning",
            showCancelButton: true,
            confirmButtonColor: "#0d6efd",
            confirmButtonText: "Yes, Change Status"
        });

        if (!confirm.isConfirmed) return;

        try {
            const data = { status: selectedStatus };
            const result = await fetch(`https://elcto-1.onrender.com/api/changestatus/${id}`, {
                method: "put",
                body: JSON.stringify(data),
                headers: { "Content-type": "application/json;charset=UTF-8" }
            });
            if (result.ok) {
                const res = await result.json();
                if (res.statuscode === 1) {
                    Swal.fire({
                        title: "Success!",
                        text: "Status changed successfully.",
                        icon: "success",
                        timer: 1500,
                        showConfirmButton: false
                    });
                    show();
                } else {
                    Swal.fire("Error", "Failed to update user status", "error");
                }
            }
        } catch (err) {
            Swal.fire("Error", "Network error updating status", "error");
        }
    };

    // Filter Logic
    const filteredUsers = d.filter(u => {
        const matchSearch = (u.FirstName && u.FirstName.toLowerCase().includes(searchTerm.toLowerCase())) ||
            (u.LastName && u.LastName.toLowerCase().includes(searchTerm.toLowerCase())) ||
            (u.Email && u.Email.toLowerCase().includes(searchTerm.toLowerCase()));
        const matchRole = roleFilter === "all" || u.UserType === roleFilter;
        const matchStatus = statusFilter === "all" || u.Status === statusFilter;
        return matchSearch && matchRole && matchStatus;
    });

    const paginatedUsers = filteredUsers.slice(
        (currentPage - 1) * itemsPerPage,
        currentPage * itemsPerPage
    );

    // Stats calculations
    const totalCount = d.length;
    const adminCount = d.filter(u => u.UserType === "admin").length;
    const activeCount = d.filter(u => u.Status === "Active").length;
    const inactiveCount = d.filter(u => u.Status === "Inactive").length;

    return (
        <>
            {utype === "admin" ? (
                <div className="container py-4">
                    {/* Header */}
                    <div className="d-flex flex-wrap justify-content-between align-items-center mb-4 pb-2 border-bottom">
                        <div>
                            <h2 className="fw-bold mb-1 text-dark">User Management</h2>
                            <p className="text-muted mb-0">View, search, filter, and manage user roles and account statuses</p>
                        </div>
                        <button className="btn btn-outline-primary d-flex align-items-center gap-2" onClick={show}>
                            <i className="bi bi-arrow-clockwise"></i> Refresh List
                        </button>
                    </div>

                    {/* Stats Dashboard */}
                    <div className="row g-3 mb-4">
                        <div className="col-md-3 col-6">
                            <div className="card border-0 shadow-sm bg-primary text-white p-3">
                                <div className="d-flex justify-content-between align-items-center">
                                    <div>
                                        <div className="small text-white-50">Total Users</div>
                                        <div className="fs-3 fw-bold">{totalCount}</div>
                                    </div>
                                    <i className="bi bi-people fs-1 text-white-50"></i>
                                </div>
                            </div>
                        </div>
                        <div className="col-md-3 col-6">
                            <div className="card border-0 shadow-sm bg-danger text-white p-3">
                                <div className="d-flex justify-content-between align-items-center">
                                    <div>
                                        <div className="small text-white-50">Admins</div>
                                        <div className="fs-3 fw-bold">{adminCount}</div>
                                    </div>
                                    <i className="bi bi-shield-lock fs-1 text-white-50"></i>
                                </div>
                            </div>
                        </div>
                        <div className="col-md-3 col-6">
                            <div className="card border-0 shadow-sm bg-success text-white p-3">
                                <div className="d-flex justify-content-between align-items-center">
                                    <div>
                                        <div className="small text-white-50">Active Users</div>
                                        <div className="fs-3 fw-bold">{activeCount}</div>
                                    </div>
                                    <i className="bi bi-check-circle fs-1 text-white-50"></i>
                                </div>
                            </div>
                        </div>
                        <div className="col-md-3 col-6">
                            <div className="card border-0 shadow-sm bg-secondary text-white p-3">
                                <div className="d-flex justify-content-between align-items-center">
                                    <div>
                                        <div className="small text-white-50">Inactive Users</div>
                                        <div className="fs-3 fw-bold">{inactiveCount}</div>
                                    </div>
                                    <i className="bi bi-x-circle fs-1 text-white-50"></i>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Filter and Control Bar */}
                    <div className="card border-0 shadow-sm mb-4">
                        <div className="card-body">
                            <div className="row g-3 align-items-center">
                                <div className="col-lg-4 col-md-6">
                                    <div className="input-group">
                                        <span className="input-group-text bg-light border-end-0">
                                            <i className="bi bi-search text-muted"></i>
                                        </span>
                                        <input
                                            type="text"
                                            className="form-control bg-light border-start-0"
                                            placeholder="Search by name or email..."
                                            value={searchTerm}
                                            onChange={(e) => {
                                                setSearchTerm(e.target.value);
                                                setCurrentPage(1);
                                            }}
                                        />
                                        {searchTerm && (
                                            <button className="btn btn-outline-secondary" onClick={() => setSearchTerm("")}>
                                                Clear
                                            </button>
                                        )}
                                    </div>
                                </div>

                                <div className="col-lg-3 col-md-3">
                                    <select
                                        className="form-select"
                                        value={roleFilter}
                                        onChange={(e) => {
                                            setRoleFilter(e.target.value);
                                            setCurrentPage(1);
                                        }}
                                    >
                                        <option value="all">All Roles</option>
                                        <option value="admin">Admin Only</option>
                                        <option value="user">User Only</option>
                                    </select>
                                </div>

                                <div className="col-lg-3 col-md-3">
                                    <select
                                        className="form-select"
                                        value={statusFilter}
                                        onChange={(e) => {
                                            setStatusFilter(e.target.value);
                                            setCurrentPage(1);
                                        }}
                                    >
                                        <option value="all">All Statuses</option>
                                        <option value="Active">Active Only</option>
                                        <option value="Inactive">Inactive Only</option>
                                    </select>
                                </div>

                                <div className="col-lg-2 col-md-12 text-lg-end">
                                    <div className="btn-group w-100" role="group">
                                        <button
                                            type="button"
                                            className={`btn ${viewMode === 'grid' ? 'btn-primary' : 'btn-outline-primary'}`}
                                            onClick={() => setViewMode('grid')}
                                        >
                                            <i className="bi bi-grid-fill me-1"></i> Grid
                                        </button>
                                        <button
                                            type="button"
                                            className={`btn ${viewMode === 'table' ? 'btn-primary' : 'btn-outline-primary'}`}
                                            onClick={() => setViewMode('table')}
                                        >
                                            <i className="bi bi-list-ul me-1"></i> Table
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Users Content Container */}
                    {loading ? (
                        <div className="text-center py-5">
                            <div className="spinner-border text-primary" role="status">
                                <span className="visually-hidden">Loading users...</span>
                            </div>
                            <p className="text-muted mt-2">Fetching user records...</p>
                        </div>
                    ) : paginatedUsers.length > 0 ? (
                        viewMode === "grid" ? (
                            /* GRID CARD VIEW */
                            <div className="row g-3">
                                {paginatedUsers.map((a) => (
                                    <div className="col-lg-4 col-md-6" key={a._id}>
                                        <div className="card h-100 border-0 shadow-sm hover-shadow transition-all">
                                            <div className="card-body p-4 d-flex flex-column justify-content-between">
                                                <div>
                                                    <div className="d-flex justify-content-between align-items-start mb-3">
                                                        <div className="d-flex align-items-center gap-3">
                                                            <div
                                                                className="rounded-circle bg-primary text-white d-flex align-items-center justify-content-center fw-bold fs-5 shadow-sm"
                                                                style={{ width: "48px", height: "48px" }}
                                                            >
                                                                {a.FirstName ? a.FirstName.charAt(0).toUpperCase() : "U"}
                                                            </div>
                                                            <div>
                                                                <h5 className="fw-bold mb-0 text-dark">{a.FirstName} {a.LastName}</h5>
                                                                <small className="text-muted d-block">{a.Email}</small>
                                                            </div>
                                                        </div>
                                                    </div>

                                                    <div className="d-flex gap-2 mb-4">
                                                        <span className={`badge ${a.UserType === 'admin' ? 'bg-danger' : 'bg-secondary'}`}>
                                                            Role: {a.UserType}
                                                        </span>
                                                        {a.Status === "Active" ? (
                                                            <span className="badge bg-success">Active</span>
                                                        ) : (
                                                            <span className="badge bg-danger">Inactive</span>
                                                        )}
                                                    </div>
                                                </div>

                                                <div className="border-top pt-3 mt-2">
                                                    <div className="row g-2">
                                                        <div className="col-6">
                                                            <label className="form-label text-muted extra-small mb-1">Role</label>
                                                            <select
                                                                className="form-select form-select-sm mb-2"
                                                                value={pendingRoles[a._id] || ""}
                                                                onChange={(e) => setPendingRoles({ ...pendingRoles, [a._id]: e.target.value })}
                                                            >
                                                                <option value="">Select</option>
                                                                <option value="admin">Admin</option>
                                                                <option value="user">User</option>
                                                            </select>
                                                            <button
                                                                className="btn btn-sm btn-primary w-100"
                                                                onClick={() => admin(a._id)}
                                                            >
                                                                Set Role
                                                            </button>
                                                        </div>

                                                        <div className="col-6">
                                                            <label className="form-label text-muted extra-small mb-1">Status</label>
                                                            <select
                                                                className="form-select form-select-sm mb-2"
                                                                value={pendingStatuses[a._id] || ""}
                                                                onChange={(e) => setPendingStatuses({ ...pendingStatuses, [a._id]: e.target.value })}
                                                            >
                                                                <option value="">Select</option>
                                                                <option value="Active">Active</option>
                                                                <option value="Inactive">Inactive</option>
                                                            </select>
                                                            <button
                                                                className="btn btn-sm btn-outline-primary w-100"
                                                                onClick={() => changeStatus(a._id)}
                                                            >
                                                                Set Status
                                                            </button>
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        ) : (
                            /* TABLE VIEW */
                            <div className="card border-0 shadow-sm">
                                <div className="table-responsive">
                                    <table className="table table-hover align-middle mb-0">
                                        <thead className="table-light">
                                            <tr>
                                                <th>User</th>
                                                <th>Email</th>
                                                <th>Status</th>
                                                <th>Current Role</th>
                                                <th>Change Role</th>
                                                <th>Change Status</th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {paginatedUsers.map((a) => (
                                                <tr key={a._id}>
                                                    <td>
                                                        <div className="d-flex align-items-center gap-2">
                                                            <div
                                                                className="rounded-circle bg-primary text-white d-flex align-items-center justify-content-center fw-bold"
                                                                style={{ width: "36px", height: "36px", fontSize: "14px" }}
                                                            >
                                                                {a.FirstName ? a.FirstName.charAt(0).toUpperCase() : "U"}
                                                            </div>
                                                            <span className="fw-semibold">{a.FirstName} {a.LastName}</span>
                                                        </div>
                                                    </td>
                                                    <td>{a.Email}</td>
                                                    <td>
                                                        {a.Status === "Active" ? (
                                                            <span className="badge bg-success">Active</span>
                                                        ) : (
                                                            <span className="badge bg-danger">Inactive</span>
                                                        )}
                                                    </td>
                                                    <td>
                                                        <span className={`badge ${a.UserType === 'admin' ? 'bg-danger' : 'bg-secondary'}`}>
                                                            {a.UserType}
                                                        </span>
                                                    </td>
                                                    <td>
                                                        <div className="d-flex align-items-center gap-1">
                                                            <select
                                                                className="form-select form-select-sm"
                                                                style={{ width: "110px" }}
                                                                value={pendingRoles[a._id] || ""}
                                                                onChange={(e) => setPendingRoles({ ...pendingRoles, [a._id]: e.target.value })}
                                                            >
                                                                <option value="">Select</option>
                                                                <option value="admin">Admin</option>
                                                                <option value="user">User</option>
                                                            </select>
                                                            <button
                                                                className="btn btn-sm btn-primary"
                                                                onClick={() => admin(a._id)}
                                                            >
                                                                Update
                                                            </button>
                                                        </div>
                                                    </td>
                                                    <td>
                                                        <div className="d-flex align-items-center gap-1">
                                                            <select
                                                                className="form-select form-select-sm"
                                                                style={{ width: "110px" }}
                                                                value={pendingStatuses[a._id] || ""}
                                                                onChange={(e) => setPendingStatuses({ ...pendingStatuses, [a._id]: e.target.value })}
                                                            >
                                                                <option value="">Select</option>
                                                                <option value="Active">Active</option>
                                                                <option value="Inactive">Inactive</option>
                                                            </select>
                                                            <button
                                                                className="btn btn-sm btn-outline-primary"
                                                                onClick={() => changeStatus(a._id)}
                                                            >
                                                                Update
                                                            </button>
                                                        </div>
                                                    </td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </div>
                            </div>
                        )
                    ) : (
                        <div className="card border-0 shadow-sm text-center py-5">
                            <i className="bi bi-people fs-1 text-muted mb-2"></i>
                            <h5 className="text-muted">No users match your criteria</h5>
                            <p className="small text-muted mb-0">Try clearing filters or search term</p>
                        </div>
                    )}

                    {/* Pagination Bar */}
                    {!loading && filteredUsers.length > 0 && (
                        <Pagination
                            totalItems={filteredUsers.length}
                            itemsPerPage={itemsPerPage}
                            currentPage={currentPage}
                            onPageChange={setCurrentPage}
                            onPerPageChange={setItemsPerPage}
                        />
                    )}
                </div>
            ) : (
                navigate("/")
            )}
        </>
    );
};
